import ui_draw as _d
import ui_fonts as _f

WIDTH = 320
HEIGHT = 240

DEFAULTS = {
    "title": "Налаштування",  # str, < 24 chars
    "brightness": 70,  # int, 0…100
    "wifi": True,  # bool
}


class UI(_d.Page):
    BACKGROUND = 0x8418  # #1a1022
    DEFAULTS = DEFAULTS
    # (id, x, y, w, h, parameters) in layer order: the first one is the lowest.
    WIDGETS = (
        ("head", 10, 6, 302, 28, ("title",)),
        ("b_bar", 10, 60, 300, 36, ("brightness",)),
        ("wifi_txt", 10, 120, 300, 28, ("wifi",)),
        ("hint", 10, 200, 300, 24, ()),
    )

    def set_title(self, value):
        self.p["title"] = value
        return self.update()

    def set_brightness(self, value):
        self.p["brightness"] = value
        return self.update()

    def set_wifi(self, value):
        self.p["wifi"] = value
        return self.update()

    def _draw_head(self, fb, ox, oy):
        # redrawn when changed: title
        p = self.p
        _d.label(
            fb,
            _d.fmt("%s", p["title"]),
            10 - ox,
            6 - oy,
            300,
            28,
            0x24ED,
            _f.SERIF_16,
            _d.LEFT,
        )

    def _draw_b_bar(self, fb, ox, oy):
        # redrawn when changed: brightness
        p = self.p
        _d.bar(
            fb,
            10 - ox,
            60 - oy,
            300,
            36,
            _d.frac(p["brightness"], 0, 100),
            0x24ED,
            "Яскравість",
            _d.num(p["brightness"], False),
            _f.SERIF_12,
        )

    def _draw_wifi_txt(self, fb, ox, oy):
        # redrawn when changed: wifi
        p = self.p
        f = "Wi-Fi: увімкнено"
        # conditions, top to bottom: the lowest one that matches wins
        if not p["wifi"]:
            f = "Wi-Fi: вимкнено"
        _d.label(fb, f, 10 - ox, 120 - oy, 300, 28, 0xFFFF, _f.MONO_16, _d.LEFT)

    def _draw_hint(self, fb, ox, oy):
        _d.label(fb, "Сторінка 2 з 2", 10 - ox, 200 - oy, 300, 24, 0x158D, _f.SERIF_12, _d.LEFT)
